svg.script:
(async()=>{
 const status=document.getElementById('status'),frame=document.getElementById('app');
 try{
  if(!navigator.serviceWorker)throw Error('This browser does not allow service workers here.');
  const base=new URL('./',location.href);
  if(base.pathname!=='/gh/Megatron963/Orbit@main/')throw Error('Use https://cdn.jsdelivr.net/gh/Megatron963/Orbit@main/orbit.svg');
  const registration=await navigator.serviceWorker.register(new URL('orbit-sw.js',base),{scope:base.href,updateViaCache:'none'});
  await Promise.race([new Promise((resolve,reject)=>{const sw=registration.installing||registration.waiting||registration.active;if(!sw)return reject(Error('Worker installation did not start.'));const check=()=>{if(sw.state==='activated')resolve();if(sw.state==='redundant')reject(Error('Worker installation failed. Check that all folders were uploaded.'));};sw.addEventListener('statechange',check);check();}),new Promise((_,reject)=>setTimeout(()=>reject(Error('Worker startup timed out.')),30000))]);
  if(!navigator.serviceWorker.controller)await Promise.race([new Promise(resolve=>{const check=()=>{if(navigator.serviceWorker.controller){navigator.serviceWorker.removeEventListener('controllerchange',check);resolve()}};navigator.serviceWorker.addEventListener('controllerchange',check);check()}),new Promise((_,reject)=>setTimeout(()=>reject(Error('Browser did not give the worker control. Reload this page.')),10000))]);
  frame.onload=()=>{status.hidden=true;frame.style.display='block'};frame.src=new URL('app',base).href;
 }catch(error){status.textContent='Orbit could not start: '+error.message;}
})();
